scripts.build:
node -e "require('node:fs').rmSync('dist',{recursive:true,force:true})" && tsc -p . && node -e "require('node:fs').writeFileSync('dist/buildInfo.js','/** @generated by npm run build (dev tree; pack/dist rewrites flag) */
export const production = false;
export const channel = "development";
')" && npm run build:renderer

scripts.pack:
npm run build && node -e "require('node:fs').writeFileSync('dist/buildInfo.js','/** @generated for release packaging */
export const production = true;
export const channel = "release";
')" && node scripts/build-release.mjs --dir

